const body = $input.first().json.body;
const target = body.target || '';
const domain = body.domain || 'general';
const depth = body.depth || 'standard';
if (!target) throw new Error('Missing required field: target');
return [{ json: { target, domain, depth, timestamp: new Date().toISOString() } }];

const { target, domain, depth } = $json;
return [{
  json: {
    task: `Perform a code review of: ${target}. Domain: ${domain}. Focus on security, correctness, maintainability, performance, testing.`,
    context: { agent_id: 'code-reviewer', code: target, language: domain, review_level: depth }
  }
}];

const cr = $input.first().json;
const crResult = cr.result || cr;
const findings = crResult.findings || [];
const blockers = findings.filter(f => f.severity === 'blocker').length;
const suggestions = findings.filter(f => f.severity === 'suggestion').length;
let score = Math.max(0, Math.min(100, 100 - blockers * 20 - suggestions * 5));
let verdict = score >= 80 ? 'READY' : score >= 60 ? 'NEEDS_WORK' : 'NOT_READY';
return [{
  json: {
    status: 'completed',
    target: $('Validate Input').first().json.target,
    domain: $('Validate Input').first().json.domain,
    readiness_score: score,
    verdict,
    code_review: { findings, summary: crResult.summary || '', severity_counts: crResult.severity_counts || {} },
    timestamp: new Date().toISOString()
  }
}];
